import express from "express";
import cors from "cors";
import { generateQuiz } from "./lib/geminiai.js";

const app = express();

app.use(cors());
app.use(express.json());

app.get("/quiz/:topic", async (req, res) => {
  const topic = req.params.topic;

  console.log("topic recevied .........", topic);

  let quizArr;
  try {
    quizArr = await generateQuiz(topic);
  } catch (error) {
    console.error("quiz generation failed:", error);
    return res.status(502).json({
      msg: "quiz generation failed",
      error: error.message,
    });
  }

  console.log("quize generated  successfully:", quizArr);

  res.json({
    msg: "quize generated successfully",
    data: quizArr,
  });
});

app.listen("8080", () => {
  console.log("server is listening at port 8080...");
});

import { GoogleGenAI } from "@google/genai";

import dotenv from "dotenv";

dotenv.config();

const GEMINI_API_KEY = process.env.GEMINI_API_KEY;
if (!GEMINI_API_KEY) {
  throw new Error("GEMINI_API_KEY is missing from .env");
}

const ai = new GoogleGenAI({ apiKey: GEMINI_API_KEY });

//generateQuize("react.js")

export const generateQuiz = async (topic) => {
  const systemPrompt =
    "Hey Gemini, Act as a expert quiz generator who is expert in generating quizes and taking examinations, I am build a AI powered quiz generator full stack application, for that generate me an array of 2  quizzes related to " +
    topic +
    " in the given format { 'question': 'how many months in a year', 'option1': '10', 'option2': '12', 'option3': '8', 'option4': '6', 'correctOption': 'option2' }. don't add any boiler plate text like ```json, send directly array of objects. I am using your response to directly convert into javascript object using 'JSON.parse' so send reponse accordingly.";

  console.log("🚀 Sending request to Gemini...");

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3.6-flash",
      contents: systemPrompt,
    });

    console.log("✅ Gemini response received!");
    console.log(response.text);

    const quizeArr = JSON.parse(response.text);

    console.log("data from ai----", quizeArr);

    return quizeArr;
  } catch (error) {
    console.error("❌ Gemini ERROR:", error);
    throw error;
  }
};

