import { useState } from 'react';
import axios from 'axios';
import './QuizGenerator.css';

const optionKeys = ['option1', 'option2', 'option3', 'option4'];

function QuizGenerator() {
  const [topic, setTopic] = useState('JavaScript');
  const [quizData, setQuizData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [selectedAnswers, setSelectedAnswers] = useState({});

  const fetchQuiz = async (event) => {
    event.preventDefault();

    const cleanTopic = topic.trim();
    if (!cleanTopic) {
      setError('Please enter a topic to generate a quiz.');
      return;
    }

    setLoading(true);
    setError('');
    setSelectedAnswers({});

    try {
      const response = await axios.get(
        `http://localhost:8080/quiz/${encodeURIComponent(cleanTopic)}`
      );

      const data = response?.data?.data ?? [];
      setQuizData(data);

      if (!data.length) {
        setError('No quiz was returned for this topic.');
      }
    } catch (err) {
      console.error('Quiz generation failed:', err);
      setError(
        err?.response?.data?.msg ||
          'Something went wrong while connecting to the server.'
      );
      setQuizData([]);
    } finally {
      setLoading(false);
    }
  };

  const handleOptionClick = (questionIndex, optionKey) => {
    setSelectedAnswers((prev) => ({
      ...prev,
      [questionIndex]: optionKey,
    }));
  };

  return (
    <section className="quiz-generator">
      <header className="quiz-header">
        <span className="eyebrow">AI QUIZ GENERATOR</span>
        <h1>Generate a practice quiz</h1>
        <p>
          Choose a topic and test your knowledge with AI-generated interview-style questions.
        </p>
      </header>

      <form className="quiz-form" onSubmit={fetchQuiz}>
        <label htmlFor="topic" className="sr-only">
          Topic
        </label>
        <input
          id="topic"
          type="text"
          value={topic}
          onChange={(e) => setTopic(e.target.value)}
          placeholder="Try: JavaScript, React, Python, AI"
        />
        <button type="submit" disabled={loading}>
          {loading ? 'Generating...' : 'Generate Quiz'}
        </button>
      </form>

      {error && <div className="status error">{error}</div>}

      {quizData.length > 0 && (
        <div className="quiz-results">
          {quizData.map((item, index) => {
            const correctAnswerKey = item.correctOption;
            const correctAnswerText = correctAnswerKey ? item[correctAnswerKey] : 'N/A';
            const selectedKey = selectedAnswers[index];
            const isAnswered = selectedKey !== undefined;
            const isCorrectSelection = selectedKey === correctAnswerKey;

            return (
              <article className="quiz-card" key={`${item.question}-${index}`}>
                <div className="question-meta">
                  <span className="badge">Question {index + 1}</span>
                </div>

                <h3>{item.question}</h3>

                <div className="options-list">
                  {optionKeys.map((key) => {
                    const value = item[key];
                    if (!value) return null;

                    const isSelected = selectedKey === key;
                    const isCorrect = key === correctAnswerKey;
                    const revealCorrect = isAnswered && isCorrect;
                    const revealWrong = isAnswered && isSelected && !isCorrect;

                    return (
                      <button
                        key={`${item.question}-${key}`}
                        type="button"
                        className={[
                          'option-btn',
                          isSelected ? 'selected' : '',
                          revealCorrect ? 'correct' : '',
                          revealWrong ? 'wrong' : '',
                        ]
                          .join(' ')
                          .trim()}
                        onClick={() => handleOptionClick(index, key)}
                        disabled={isAnswered}
                      >
                        <span className="option-label">{key.replace('option', 'Option ')}</span>
                        <span>{value}</span>
                      </button>
                    );
                  })}
                </div>

                {isAnswered && (
                  <p className={`answer-box ${isCorrectSelection ? 'success' : 'error'}`}>
                    <strong>{isCorrectSelection ? 'Correct!' : 'Incorrect.'}</strong>{' '}
                    {correctAnswerText}
                  </p>
                )}
              </article>
            );
          })}
        </div>
      )}
    </section>
  );
}

export default QuizGenerator;
